<?php
// Original deliveries design: real trips, ready orders and the SSTF dispatch proposal.
use App\Services\Workspace;
use App\UI\LiveForm as F;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$live = Workspace::get()->load(static fn (Workspace $w): array => $w->dispatch());
if (isset($live['error'])): ?><?= U::heading('Deliveries') ?><section class="panel p-6" role="alert"><?= U::e($live['error']) ?></section><?php return; endif;
$queryTab = $_GET['tab'] ?? 'active'; $tab = is_string($queryTab) && in_array($queryTab, ['active','ready','completed'], true) ? $queryTab : 'active';
$pv = $live['preview']; $proposal = $pv['proposal'] ?? null;
$trips = $live['trips']; $ready = $live['ready_delivery'];
$active = count(array_filter($trips, fn($t) => $t['status'] === 'active')); $done = count($trips) - $active;
$free = count(array_filter($live['riders'], fn($r) => $r['free']));
?>
<?= U::heading('Deliveries','Build and monitor your station’s delivery trips.',U::btn('Build a trip','/station-admin/deliveries#dispatch','primary','plus')) ?>
<div class="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4"><?= U::stat('Active trips',(string)$active,'truck','blue','Out on the road now','Live') ?><?= U::stat('Ready to dispatch',(string)count($ready),'check','green','Delivery orders waiting','Ready') ?><?= U::stat('Available riders',(string)$free,'users','violet','Can take the next trip','Riders') ?><?= U::stat('Completed trips',(string)$done,'clock','amber','Closed this week','Done') ?></div>
<?= U::tabs(['/station-admin/deliveries'=>'Active trips','/station-admin/deliveries?tab=ready'=>'Ready to dispatch','/station-admin/deliveries?tab=completed'=>'Completed'],$tab==='active'?'/station-admin/deliveries':'/station-admin/deliveries?tab='.$tab) ?>
<div class="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_340px]"><section class="panel p-4 md:p-5"><?= U::title($tab==='ready'?'Ready to dispatch':($tab==='completed'?'Completed trips':'Active trips'), $tab==='ready'?'check':($tab==='completed'?'clock':'truck'), 'mb-4') ?>
<?php if($tab==='ready'): ?><?= $ready === [] ? '<p class="p-5 text-center text-sm text-muted">No delivery order is ready.</p>' : U::table(['Order','Customer','Barangay','Containers'],array_map(fn($o)=>[U::e($o['order_no']).($o['redispatch_paused'] ? ' '.U::badge('Paused','amber') : ''),U::e($o['customer_name'] ?? ''),U::e($o['barangay'] ?? ''),(int) $o['load_units']],$ready)) ?>
<?php else: $rows=[]; foreach($trips as $trip) { if(($tab==='completed')!==($trip['status']==='closed')) continue; $rows[]=['<strong>Trip '.(int)$trip['trip_no'].'</strong>',U::e($trip['rider_name']),U::e($trip['barangay'] ?? ''),(int)$trip['load_units'].' / '.(int)$trip['capacity'],(int)$trip['resolved'].' / '.(int)$trip['stops'],U::badge($trip['status']==='closed'?'Completed':'In progress',$trip['status']==='closed'?'green':'amber'),U::btn('View trip','/station-admin/trip?trip='.$trip['id'],'secondary','eye')]; } ?><?= $rows === [] ? '<p class="p-5 text-center text-sm text-muted">No trips here yet.</p>' : U::table(['Trip','Driver','Area','Load','Stops','Status','Action'],$rows) ?><?php endif ?></section>
<aside class="panel h-fit scroll-mt-24 p-4 md:p-5" id="dispatch"><?= U::title('Dispatch new trip','truck','mb-4') ?>
<?php foreach ($pv['warnings'] ?? [] as $w): ?><p class="mb-3 rounded-lg bg-amber-50 p-3 text-xs text-amber-900"><strong><?= U::e($w['order_no']) ?></strong> (<?= (int) $w['load'] ?>): <?= U::e($w['message']) ?></p><?php endforeach ?>
<?php if ($proposal === null): ?><p class="rounded-xl bg-foam p-3.5 text-sm"><?= U::e($pv['message'] ?? 'No ready delivery order is due within the hour. Orders appear here when they are ready.') ?></p>
<?php else: $riders = [$proposal['rider_id'] => $proposal['rider_name'].' · Available · '.$proposal['capacity'].' containers']; foreach ($pv['other_riders'] as $r) $riders[$r['rider_id']] = $r['name'].' · Available · '.$r['capacity'].' containers'; $overdue = array_filter($proposal['stops'], fn($s) => $s['overdue']); ?>
<?= F::open('/station-admin/dispatch', [], ['class' => 'space-y-4']) ?><?= U::select('Rider','rider_id',$riders,$proposal['rider_id'],['required'=>true]) ?><?= U::select('Barangay','area',[$proposal['barangay'] ?? '' => $proposal['barangay'] ?? 'Not set'],$proposal['barangay'] ?? '') ?>
<div class="rounded-xl bg-foam p-3.5"><p class="flex items-center gap-2 text-sm font-semibold"><?= U::icon('orders','size-4 text-water') ?>Selected ready orders · nearest stop first</p><ul class="mt-2 space-y-1.5"><?php foreach($proposal['stops'] as $s): ?><li><label class="flex items-center justify-between gap-3 rounded-lg bg-white px-3 py-2 text-sm"><span class="flex items-center gap-2"><input type="checkbox" name="order_ids[]" value="<?= U::e($s['order_id']) ?>" checked class="accent-cyan-600"><span><strong><?= (int) $s['sequence'] ?>. <?= U::e($s['order_no']) ?></strong> <span class="text-muted"><?= U::e($s['customer_name'] ?? '') ?> · <?= U::e(number_format((float) $s['leg_km'], 1)) ?> km</span></span></span><span class="flex items-center gap-1 whitespace-nowrap"><?= U::icon('bottle','size-4 text-water') ?><?= (int) $s['load'] ?></span></label></li><?php endforeach; ?></ul><div class="mt-3 flex items-center justify-between border-t border-line pt-3 font-bold"><span class="flex items-center gap-2"><?= U::icon('truck','size-4 text-water') ?>Total load</span><span><?= (int) $proposal['load'] ?> / <?= (int) $proposal['capacity'] ?></span></div></div>
<?php if ($overdue !== []): ?><details class="text-sm"><summary class="cursor-pointer font-semibold text-water">Move an overdue stop first</summary><div class="mt-2 space-y-2"><?= U::select('Overdue stop','front_order_id',[''=>'Keep nearest-first order'] + array_column(array_map(fn($s)=>['id'=>$s['order_id'],'no'=>$s['order_no']],$overdue),'no','id')) ?><?= U::field('Reason','front_reason','','text',['maxlength'=>'300']) ?></div></details><?php endif ?>
<div class="grid gap-2"><?= U::btn('Dispatch trip','','primary','truck',['type'=>'submit','data-confirm'=>'Dispatch this trip? The orders go out for delivery.']) ?><?= U::btn('View active trip',isset($trips[0]) ? '/station-admin/trip?trip='.$trips[0]['id'] : '/station-admin/deliveries','ghost','eye') ?></div></form><?php endif ?></aside></div>
